sys_script_include.script:
var kotak_validations = Class.create();
kotak_validations.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    loan_number_records: function(policySys) {

        var lnRecords = [];

        var uwCase = new GlideRecord("x_rptp_kotak_uw_case");
        uwCase.addQuery("policy_id", policySys);
        uwCase.query();

        while (uwCase.next()) {
            lnRecords.push(uwCase.getValue("loan_number"));
        }

        return 'sys_idIN' + lnRecords;
    },

    getLoanSys_client: function() {

        var policySys = this.getParameter('policySys');
        return this.loan_number_records(policySys);
    },

    member_dep_records: function(policySys, loanSys) {

        var memRecords = [];

        var uwCase = new GlideRecord("x_rptp_kotak_uw_case");
        uwCase.addQuery("policy_id", policySys);
        uwCase.addQuery("loan_number", loanSys);
        uwCase.query();

        while (uwCase.next()) {
            memRecords.push(uwCase.getValue("consumer_id"));
        }

        return 'sys_idIN' + memRecords;
    },

	getMemberSys_client: function() {

        var policySys = this.getParameter('policySys');
		var loanSys = this.getParameter('loanSys');
        return this.member_dep_records(policySys,loanSys);
    },

    type: 'kotak_validations'
});
